if ~exist('src400s','var')
    src400s = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei401_align_sym3.sqw');
end
file = src400s.full_filename %[output:4707b371]
[~,fname] = fileparts(file);
w2_00 = cut(src400s,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]);
plot(w2_00);lz 0 1;liny; keep_figure; %[output:398b7820]

data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits\' %[output:79e5ddab]
fit_cuts_file = 'multicuts_fit_dataHN_ei400meV.mat' %[output:98ab52bb]
cuts_res_file = fullfile(data_path,fit_cuts_file);
if ~exist('cuts2fit200HN','var')
    cuts2fit400HN = recover_cuts_2fit(cuts_res_file,'cuts2fit400HN');
end

hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;
%%
Add_bins = {[-0.1,0.1],[-0.1,0.1],[0,4,350]};

%w2_400a1 = cut(src400s,line_proj([1,1,0],[-1,1,0],'offset',[0.5,1.5,0]),[0.04],[-0.1,0.1],[-0.1,0.1],[0,5,500]);
%plot(w2_400a1);liny; lz 0 1;keep_figure;
%w2_400a2 = cut(src400s,line_proj([1,1,0],[-1,1,0],'offset',[1.5,0.5,0]),[0.04],[-0.1,0.1],[-0.1,0.1],[0,5,500]);
%plot(w2_400a2); lz 0 1;keep_figure;

w2_400a = cut(src400s,line_proj([1,1,0],[-1,1,0],'offset',[0.5,1.5,0]),0.02,Add_bins{:},SymopReflection('norm',[-1,1,0],'offset',[1,1,0]));
plot(w2_400a);liny; lz 0 0.3;keep_figure; %[output:50df639c]


w2_400b = cut(src400s,line_proj([-1,1,0],[1,1,0],'offset',[2,1,0]),0.02,Add_bins{:});
plot(w2_400b); lz 0 0.3;keep_figure; %[output:7b822ae6]


% w2_400c = cut(src400s,line_proj([1,1,0],[-1,1,0],'offset',[1,1,1]),[0.04],[-0.1,0.1],[-0.1,0.1],[0,5,500],SymopReflection('norm',[-1,1,0],'offset',[1,1,0]));
% plot(w2_400c);liny; lz 0 0.3;keep_figure;

%%
scuts_path = 'e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts';
allJfitfile = fullfile(scuts_path,'J0_3fitOff110Cuts');
if ~exist('multij_110','var')
    multij_110 = [];
end
multij_110 = save_selected_cuts(multij_110,allJfitfile, ...
    'Ei400_off210HN',cut(w2_400b,[0,0.02,1],[140,2,230]));
%%
bg_400b2 = cut(src400s,line_proj([-1,1,0],[1,1,0],'offset',[3,2,0]),0.04,Add_bins{:});
plot(bg_400b2);liny; lz 0 0.1;keep_figure; %[output:2703e8df]

bg1 = cut(src400s,line_proj([-1,1,0],[1,1,0],'offset',[3,2,0]),[-1,2],Add_bins{:});
plot(bg1);logy; keep_figure; %[output:8eb45fea]

%%
w2nbg = repmat(sqw,1,2);
w2nbg(1) = w2_400a - replicate(bg1,w2_400a);
w2nbg(1) = cut(w2nbg(1),[-0.5,0.02,1.5],[0,4,350]);
plot(w2nbg(1));liny; lz 0 0.1;keep_figure; %[output:759362bd]

w2nbg(2) = w2_400b - replicate(bg1,w2_400b);
w2nbg(2) = cut(w2nbg(2),[-1,0.02,2],[0,4,350]);
plot(w2nbg(2));liny; lz 0 0.1;keep_figure; %[output:6bff3efb]
%%
save(cuts_res_file,'cuts2fit200NG','-v7.3');
%%
if ~exist('mion','var')
    mion = MagneticIons();
end
w2nbgc = repmat(sqw,1,2);
for i=1:2 %[output:group:0b0ec450]
    w2nbgc(i) = mion.correct_mag_ff(w2nbg(i));
    plot(w2nbgc(i)); lz 0 1;keep_figure;drawnow %[output:6e716306] %[output:7333a8d8]
end %[output:group:0b0ec450]
%%
 w2s1 = symmetrise_sqw(w2nbgc(2),{SymopReflection('norm',[-1,1,0],'offset',[2,1,0]),SymopReflection('norm',[1,-1,0],'offset',[1,2,0])});
 plot(w2s1); lz 0 1;keep_figure; %[output:2e1e9931]
%%
w2s2 = symmetrise_sqw(w2s1,SymopReflection('norm',[1,-1,0],'offset',[1.5,1.5,0]));

w2s2.full_filename = [fname,' HN Ei400, one cut sum, bg removed, ff corrected'];
plot(w2s2); lz 0 1;keep_figure; %[output:456a26fb]
%%
ff = gcf %[output:5521e1ec]
savefig(ff,'sHN_Ei400_2Sym_bg_rem_ff_corr');


